#!/usr/bin/env python3
"""Write docs/PARAMETERS.md from shared/parameters.json (single source of truth)."""
import json
import os

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
P = json.load(open(os.path.join(ROOT, "shared", "parameters.json"), encoding="utf-8"))
SEM = P["renderers"]["semantic-grating"]
LEG = P["renderers"]["legacy-rectified"]
out = ["# Parameter reference", "",
       "Generated by `tools/param_table.py` from `shared/parameters.json`. Ranges are interface bounds, not physiological bounds.",
       "`step` is the fine slider step and the quantisation grid (values snap to `min + k*step`); `coarse` is the coarse slider step;",
       "`proposal` is the base displacement used for coarse alternatives (fine = 0.25x; each repeat multiplies by the shrink factor, default 0.6).", "",
       "## semantic-grating %s" % SEM["version"], "", SEM["description"], "",
       "| family | path | label | range | step | coarse | proposal | default | unit | notes |", "|---|---|---|---|---|---|---|---|---|---|"]
for d in SEM["params"]:
    rng = " / ".join(d["choices"]) if d["type"] == "enum" else "%s … %s" % (d["min"], d["max"])
    notes = ", ".join(x for x in ["advanced" if d.get("advanced") else "", "periodic %s" % d["periodic"] if d.get("periodic") else "",
                                  "integer" if d.get("integer") else "",
                                  "activates family" if SEM["families"][d["family"]]["activator"] == d["key"] else ""] if x)
    out.append("| %s | `%s` | %s | %s | %s | %s | %s | %s | %s | %s |" % (d["family"], d["key"], d["label"], rng, d.get("step", ""), d.get("coarseStep", ""),
                                                                    d.get("proposal", ""), d["default"], d.get("unit", ""), notes))
out += ["", "## legacy-rectified %s" % LEG["version"], "", LEG["description"], "",
        "Paths: `contrast`, and `c<ID>.<field>` for component ID (e.g. `c3.weight`, `c3.enabled`). Up to %d components." % LEG["maxComponents"], "",
        "| field | JSON key | range | step | coarse | proposal | notes |", "|---|---|---|---|---|---|---|"]
for d in [LEG["contrast"]] + LEG["componentParams"]:
    out.append("| %s | `%s` | %s … %s | %s | %s | %s | %s |" % (d["label"], d["key"], d["min"], d["max"], d["step"], d["coarseStep"], d["proposal"],
                                                        ("relative %s×|value| if larger" % d["proposalRel"]) if d.get("proposalRel") else ""))
out += ["", "## Gallery templates", "", P["gallery"]["notes"], "", "| family | mild | strong |", "|---|---|---|"]
for f in P["gallery"]["families"]:
    out.append("| %s (`%s`) | `%s` | `%s` |" % (f["label"], f["id"], json.dumps(f["mild"]), json.dumps(f["strong"])))
out += ["", "Pre-built combinations: " + ", ".join(" + ".join(c) for c in P["gallery"]["combinations"]) + ".", ""]
open(os.path.join(ROOT, "docs", "PARAMETERS.md"), "w", encoding="utf-8").write("\n".join(out))
print("wrote docs/PARAMETERS.md")
